<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('recruiter');$user=current_user();$flashes=render_flashes();$currentPage='activity_log';$pageTitle='Activity Log';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$rows=[];$exists=rc_has_table($conn,'recruiter_activity_log');if($exists){$s=$conn->prepare("SELECT * FROM recruiter_activity_log WHERE recruiter_id=? ORDER BY created_at DESC,id DESC LIMIT 200");$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}require __DIR__.'/_layout_start.php';?><div class="rc-page-header"><span class="rc-eyebrow">Audit & Accountability</span><h2>Activity Log</h2><p>Candidate access and shortlist actions recorded for your Recruiter account.</p></div><?php if(!$exists):?><div class="rc-alert rc-alert--warning"><i class="fas fa-database"></i><div>Import database/recruiter_portal.sql to enable the activity log.</div></div><?php endif;?><div class="rc-card"><div class="rc-activity-list"><?php if(!$rows):?><div class="rc-empty"><i class="fas fa-clock-rotate-left"></i><strong>No activity recorded</strong></div><?php else:foreach($rows as $x):?><article><i class="fas fa-fingerprint"></i><div><div><strong><?=e(rc_label($x['action']))?></strong><span><?=e(rc_datetime($x['created_at']))?></span></div><p><?=e($x['description'])?></p></div></article><?php endforeach;endif;?></div></div><?php require __DIR__.'/_layout_end.php';?>